  return (
    <FlatList
      testID="products/list"
      data={items}
      keyExtractor={p => p.id}
      renderItem={({ item }) => <ProductRow item={item} stock={stock[item.id] ?? 0} onPress={() => navigation.navigate('Product', { id: item.id })} />}
    />
  );
}
